/**
 * What LeadDTO promises about itself, checked here as a courtesy.
 *
 * The server enforces these when the row is written - that is what
 * makes them true. This is so a form can say what is wrong before
 * the request, in the domain's own words.
 *
 * @returns the promises this value breaks, empty when it keeps them
 */
export function violations(lead: LeadDTO | null | undefined): string[] {
    const broken: string[] = [];
    if (lead == null) return broken;
    if (lead.estimatedValue != null && Number(lead.estimatedValue) < 0) {
        broken.push('estimatedValue must be at least 0');
    }
    return broken;
}

/** Whether LeadDTO keeps every promise it makes. */
export function isValid(lead: LeadDTO | null | undefined): boolean {
    return violations(lead).length === 0;
}
